package com.johnny.hotel.repair;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.inspection.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.task.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import static com.johnny.hotel.service.support.BillingRules.*;
@Service@RequiredArgsConstructor public class RepairOrderServiceImpl implements RepairOrderService{private final RepairOrderMapper db;private final InspectionMapper inspections;private final HotelTaskService tasks;private final RepairAccess access;private final PaginationSupport pagination;private final Clock clock;
 private LocalDateTime now(){return LocalDateTime.now(clock).truncatedTo(ChronoUnit.MICROS);}private String note(String v){if(v==null||v.isBlank())return null;v=v.trim();require(v.length()<=500,"Notes must be at most 500 characters");return v;}
 @Override@Transactional(propagation=Propagation.MANDATORY)public RepairOrder createForInspection(RoomInspection i,String description,Long actor){require(i!=null&&i.getId()!=null,"Inspection is required");var old=db.byInspection(i.getId());if(old!=null)return old;String issue=note(description);require(issue!=null,"Structural damage description is required");var task=tasks.createRepair(i.getRoomId(),"ROOM_REPAIR_INSPECTION:"+i.getId(),issue,actor);var order=RepairOrder.builder().taskId(task.getId()).inspectionId(i.getId()).roomId(i.getRoomId()).issueDescription(issue).priority(RepairPriority.CRITICAL.getCode()).status(RepairOrderStatus.OPEN.getCode()).build();one(db.insert(order));return db.find(order.getId());}
 @Override public RepairOrder get(Long id){access.read();var r=db.find(id);if(r==null)throw new BusinessException(404,"Repair order does not exist");return r;}
 @Override public PageResult<RepairOrder> list(Long room,Integer status,Long inspection,Integer page,Integer size){access.read();if(status!=null)RepairOrderStatus.fromCode(status);boolean search=room!=null||status!=null||inspection!=null;var w=pagination.window(page,size,search);int limit=pagination.limit(w);return pagination.result(w,limit==0?List.of():db.page(room,status,inspection,w.offset(),limit),db.count(room,status,inspection));}
 @Override@Transactional public RepairOrder complete(Long id,RepairRequests.Complete request,boolean force){var actor=force?access.manage():access.operate();var order=db.lock(id);require(order!=null,"Repair order does not exist");if(order.getStatus()==RepairOrderStatus.COMPLETED.getCode())return order;require(order.getStatus()==RepairOrderStatus.OPEN.getCode()||order.getStatus()==RepairOrderStatus.IN_PROGRESS.getCode(),"Repair order cannot be completed");if(!force)require(order.getStatus()==RepairOrderStatus.IN_PROGRESS.getCode(),"Repair Todo must be acknowledged before completion");BigDecimal cost=request==null||request.getActualCost()==null?null:money(request.getActualCost(),12);if(cost!=null)require(cost.signum()>=0,"Actual cost cannot be negative");String notes=note(request==null?null:request.getNotes());tasks.completeRepair(order.getTaskId(),notes,force);one(db.complete(id,cost,notes,actor.id(),now()));createReinspection(order);return db.find(id);}
 @Override@Transactional public RepairOrder cancel(Long id,String notes){var actor=access.manage();var order=db.lock(id);require(order!=null,"Repair order does not exist");if(order.getStatus()==RepairOrderStatus.CANCELLED.getCode())return order;require(order.getStatus()==RepairOrderStatus.OPEN.getCode()||order.getStatus()==RepairOrderStatus.IN_PROGRESS.getCode(),"Repair order cannot be cancelled");String normalized=note(notes);tasks.cancelRepair(order.getTaskId(),normalized);one(db.cancel(id,normalized,actor.id(),now()));createReinspection(order);return db.find(id);}
 private void createReinspection(RepairOrder order){if(inspections.byRepair(order.getId())!=null)return;var source=inspections.lock(order.getInspectionId());require(source!=null,"Source inspection does not exist");var next=RoomInspection.builder().roomId(source.getRoomId()).stayId(source.getStayId()).assignmentId(source.getAssignmentId()).turnoverTaskId(source.getTurnoverTaskId()).repairOrderId(order.getId()).build();one(inspections.insertForRepair(next));}
}
